/* =====================================================================
   M3M_1.O  —  Step 5 (OPTIONAL): fictional sample data for testing
   Run in SSMS against M3M_One after 02_schema.sql.
   Do NOT run on the live database. Adds demo users (password Password@123) and 11 fictional projects.
   ===================================================================== */
USE [M3M_One];
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO


IF EXISTS (SELECT 1 FROM dbo.projects)
BEGIN
    RAISERROR(N'Projects already exist - sample data skipped', 10, 1) WITH NOWAIT;
    SET NOEXEC ON;
END
GO

BEGIN TRY
BEGIN TRANSACTION;

-- users (20 rows)
SET IDENTITY_INSERT dbo.users ON;
SET IDENTITY_INSERT dbo.users OFF;

-- projects (11 rows)
SET IDENTITY_INSERT dbo.projects ON;
SET IDENTITY_INSERT dbo.projects OFF;

-- projectModules (208 rows)
SET IDENTITY_INSERT dbo.projectModules ON;
SET IDENTITY_INSERT dbo.projectModules OFF;

-- projectChapters (27 rows)
SET IDENTITY_INSERT dbo.projectChapters ON;
SET IDENTITY_INSERT dbo.projectChapters OFF;

-- chapterFieldValues (766 rows)
SET IDENTITY_INSERT dbo.chapterFieldValues ON;
SET IDENTITY_INSERT dbo.chapterFieldValues OFF;

-- keyRatios (3 rows)
SET IDENTITY_INSERT dbo.keyRatios ON;
SET IDENTITY_INSERT dbo.keyRatios OFF;

-- comKeyRatios (2 rows)
SET IDENTITY_INSERT dbo.comKeyRatios ON;
SET IDENTITY_INSERT dbo.comKeyRatios OFF;

-- designBriefSummaries (2 rows)
SET IDENTITY_INSERT dbo.designBriefSummaries ON;
SET IDENTITY_INSERT dbo.designBriefSummaries OFF;

-- designBriefComments (1 rows)
SET IDENTITY_INSERT dbo.designBriefComments ON;
SET IDENTITY_INSERT dbo.designBriefComments OFF;

-- notifications (2 rows)
SET IDENTITY_INSERT dbo.notifications ON;
SET IDENTITY_INSERT dbo.notifications OFF;

-- auditLogs (46 rows)
SET IDENTITY_INSERT dbo.auditLogs ON;
SET IDENTITY_INSERT dbo.auditLogs OFF;

-- contributorTasks (7 rows)
SET IDENTITY_INSERT dbo.contributorTasks ON;
SET IDENTITY_INSERT dbo.contributorTasks OFF;

-- designBriefInputs (4 rows)

COMMIT TRANSACTION;
PRINT 'Sample data loaded.';
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    PRINT 'Nothing was loaded - error: ' + ERROR_MESSAGE();
    THROW;
END CATCH
GO
SET NOEXEC OFF;
GO
